import { expect, test, type Page } from "@playwright/test";
import recorded from "./fixtures/admin-responses.json";

// 03E2 Reports catalogue, builder and export views in the real production build. The backend is mocked at the network layer with the RECORDED real registry
// (frontend/e2e/fixtures/admin-responses.json, generated by scripts/gen_w11_admin_fixture.py); previews, saved reports and exports are deterministic fixtures.
// The real suppression, authorization and audit behaviour is proven by tests/test_report_builder_03e1.py (backend).

const REC = recorded as Record<string, any>;
const json = (route: any, body: unknown, status = 200, headers: Record<string, string> = {}) =>
  route.fulfill({ status, contentType: "application/json", headers: { "x-request-id": "r", ...headers }, body: JSON.stringify(body) });
const account = (perms: string[]) => ({ user_id: 1, email: "ops@example.com", display_name: null, platform_role: "x", tier: "basic", status: "active", email_verified: true, providers: ["password"],
  auth_method: "session", capabilities: [], admin_permissions: perms, response_detail: "brief", interface_locale: "en", conversation_language: "en", coaching_style: "balanced",
  career_geography: "", target_role: "", onboarding_completed: true, onboarding_step: 0 });

const STD = ["platform.overview.read", "platform.reports.read"];
const COM = ["platform.overview.read", "platform.reports.commercial.read"];

const preview = (q: URLSearchParams) => {
  const ids = q.getAll("metric_ids");
  const grouped = q.get("group_by");
  return { report_id: q.get("report_id"), title: "Product report", window: q.get("window"), window_start: "2026-09-22T00:00:00+00:00", window_end: "2026-10-22T00:00:00+00:00",
    generated_at: "2026-10-22T00:00:00+00:00", utc: true, group_by: grouped, filters: [], chart: q.get("chart"), comparison: q.get("comparison") ?? "none",
    previous_window_start: null, previous_window_end: null, privacy: "Aggregates only. Candidate cohorts below the engineering privacy floor are suppressed.",
    metrics: ids.map((id) => grouped ? { metric_id: id, label: id, unit: "count", period: "30d", coverage: "Historical", suppression: "cohort", state: "ok", value: null, partial: false, note: "",
      group_dimension: grouped, previous: null, buckets: [{ label: "bug", state: "ok", value: 12 }, { label: "idea", state: "suppressed", value: null }, { label: "praise", state: "ok", value: 8 }] }
      : { metric_id: id, label: id, unit: "count", period: "30d", coverage: "Historical", suppression: "cohort", state: id === "onboarding_rate" ? "suppressed" : "ok",
        value: id === "onboarding_rate" ? null : 42, partial: false, note: "", group_dimension: null, buckets: null, previous: null }) };
};

async function mock(page: Page, perms: string[], theme: "light" | "dark" = "light", opts: { malformedPreview?: boolean; malformedStandard?: boolean; exportStatus?: number } = {}) {
  const seen: { method: string; path: string; body?: any }[] = [];
  await page.addInitScript((th) => { try { window.localStorage.setItem("iic-theme", th); } catch { /* ignore */ } }, theme);
  await page.route("**/api/v1/**", async (route) => {
    const req = route.request();
    const url = new URL(req.url());
    const path = url.pathname.replace(/^\/api\/v1/, "");
    seen.push({ method: req.method(), path, body: req.postData() ? JSON.parse(req.postData()!) : undefined });
    if (path.endsWith("/capabilities")) return json(route, { agent_coach_enabled: false, company_research_enabled: false });
    if (path.endsWith("/auth/me")) return json(route, account(perms));
    if (/\/admin\/reports\/[a-z-]+$/.test(path)) return opts.malformedStandard ? json(route, { sections: "nope" }) : json(route, REC[path]);
    if (path.endsWith("/registry")) return json(route, REC[path]);
    if (path.endsWith("/saved")) return json(route, { items: [], max_saved: 25 });
    if (path.endsWith("/validate")) return json(route, { valid: true, problems: [] });
    if (path.endsWith("/preview")) return json(route, opts.malformedPreview ? { nonsense: 1 } : preview(url.searchParams));
    if (path.endsWith("/export")) {
      if (opts.exportStatus && opts.exportStatus !== 200) return json(route, { error: { code: "http_503", message: "The export could not be audited, so nothing was exported.", request_id: "r" } }, opts.exportStatus);
      return route.fulfill({ status: 200, contentType: "text/csv; charset=utf-8", headers: { "access-control-expose-headers": "Content-Disposition, X-Export-Rows", "content-disposition": 'attachment; filename="ask4mo-product-30d-20261022.csv"', "x-export-rows": "1" }, body: "a,b\r\n" });
    }
    return json(route, {});
  });
  return seen;
}

async function openBuilder(page: Page) {
  await page.goto("/admin/reports");
  await expect(page.getByRole("heading", { name: "Reports", exact: true, level: 1 })).toBeVisible();
  await page.getByRole("button", { name: "Catalogue and builder" }).click();
  await expect(page.getByRole("heading", { name: "Builder", exact: true })).toBeVisible();
  await expect(page.getByText("Definition is valid")).toBeVisible();
}

test("03E2: catalogue, builder, preview with suppression, chart with data table, and CSV export", async ({ page }) => {
  const seen = await mock(page, STD);
  await openBuilder(page);
  await expect(page.getByRole("heading", { name: "Report catalogue" })).toBeVisible();
  // only registry choices: the single textbox is the saved-report name
  await expect(page.getByRole("textbox")).toHaveCount(1);
  await page.getByRole("checkbox", { name: /Onboarding completion of period registrants/ }).first().check();
  await page.getByLabel("Chart").selectOption("distribution");
  await expect(page.getByText("Definition is valid")).toBeVisible();
  await page.getByRole("button", { name: "Run preview" }).click();
  await expect(page.getByRole("heading", { name: /Preview:/ })).toBeVisible();
  await expect(page.getByText("Suppressed: small cohort").first()).toBeVisible();
  await expect(page.getByRole("table", { name: /Data table/ }).first()).toBeVisible();
  const download = page.waitForEvent("download");
  await page.getByRole("button", { name: "Export CSV" }).click();
  expect((await download).suggestedFilename()).toBe("ask4mo-product-30d-20261022.csv");
  await expect(page.getByText(/Downloaded ask4mo-product-30d-20261022\.csv/)).toBeVisible();
  const exp = seen.find((s) => s.path.endsWith("/export"))!;
  expect(exp.method).toBe("POST");
  expect(Object.keys(exp.body.definition).sort()).toEqual(["chart", "comparison", "filters", "group_by", "metric_ids", "report_id", "window"]);
  expect(seen.some((s) => s.path.includes("commercial"))).toBe(false);
});

test("03E2: PDF export downloads an application/pdf file and shows the audited notice", async ({ page }) => {
  await mock(page, STD);
  await page.route("**/api/v1/admin/report-builder/export", async (route) => route.fulfill({ status: 200, contentType: "application/pdf",
    headers: { "access-control-expose-headers": "Content-Disposition, X-Export-Rows", "content-disposition": 'attachment; filename="ask4mo-product-30d-20261022.pdf"', "x-export-rows": "1" }, body: "%PDF-1.4\n%%EOF\n" }));
  await openBuilder(page);
  const download = page.waitForEvent("download");
  await page.getByRole("button", { name: "Export PDF" }).click();
  expect((await download).suggestedFilename()).toBe("ask4mo-product-30d-20261022.pdf");
  await expect(page.getByText(/Downloaded ask4mo-product-30d-20261022\.pdf/)).toBeVisible();
});

test("03E2: grouped preview offers its bucket labels as the only filter choices", async ({ page }) => {
  await mock(page, STD);
  await openBuilder(page);
  await page.getByRole("button", { name: "Use Quality in the builder" }).click();       // the first metric of the report (Candidate feedback) is preselected
  await expect(page.getByRole("checkbox", { name: /Candidate feedback/ })).toBeChecked();
  await page.getByLabel("Group by").selectOption({ index: 1 });
  await page.getByRole("button", { name: "Run preview" }).click();
  await expect(page.getByRole("checkbox", { name: "bug" })).toBeVisible();
  await expect(page.getByRole("checkbox", { name: "idea" })).toBeVisible();
});

test("03E2: a 503 audit failure shows an explicit error and no file; a malformed preview shows the explicit error", async ({ page }) => {
  await mock(page, STD, "light", { exportStatus: 503 });
  await openBuilder(page);
  let downloaded = false;
  page.on("download", () => { downloaded = true; });
  await page.getByRole("button", { name: "Export JSON" }).click();
  await expect(page.getByText(/nothing was exported\. No file was downloaded\./)).toBeVisible();
  expect(downloaded).toBe(false);
});

test("03E2: a malformed 200 preview renders the explicit error and does not crash", async ({ page }) => {
  await mock(page, STD, "light", { malformedPreview: true });
  await openBuilder(page);
  await page.getByRole("button", { name: "Run preview" }).click();
  await expect(page.getByText(/unexpected form/)).toBeVisible();
  await expect(page.getByRole("heading", { name: "Builder", exact: true })).toBeVisible();
});

test("03E2: a malformed 200 from the standard reports endpoint shows the explicit Admin error state instead of crashing", async ({ page }) => {
  await mock(page, STD, "light", { malformedStandard: true });
  await page.goto("/admin/reports");
  await expect(page.getByRole("heading", { name: "Reports", exact: true, level: 1 })).toBeVisible();
  await expect(page.getByRole("alert").filter({ hasText: "That request could not be processed." })).toBeVisible();
  await page.getByRole("button", { name: "Catalogue and builder" }).click();
  await expect(page.getByRole("heading", { name: "Builder", exact: true })).toBeVisible();
});

test("03E2: commercial reports only for the commercial permission", async ({ page }) => {
  const seen = await mock(page, COM);
  await openBuilder(page);
  await expect(page.getByText(/MOCK BILLING: NOT LIVE REVENUE/).first()).toBeVisible();
  expect(seen.some((s) => s.path === "/admin/report-builder/registry")).toBe(false);
  expect(seen.some((s) => s.path === "/admin/report-builder/commercial/registry")).toBe(true);
  await page.getByRole("checkbox", { name: /Mock MRR/ }).check();                       // a per-currency metric forces its grouping dimension
  await expect(page.getByLabel("Group by")).toBeDisabled();
});

for (const [w, h] of [[1280, 800], [768, 1024]] as const) {
  for (const theme of ["light", "dark"] as const) {
    test(`03E2 visual/a11y: builder with preview, ${w}px, ${theme}`, async ({ page }) => {
      await page.setViewportSize({ width: w, height: h });
      await mock(page, [...STD, ...COM.slice(1)], theme);
      await openBuilder(page);
      await page.getByLabel("Chart").selectOption("share_of_whole");
      await page.getByRole("button", { name: "Run preview" }).click();
      await expect(page.getByRole("heading", { name: /Preview:/ })).toBeVisible();
      const r = await page.evaluate(() => {
        const vw = document.documentElement.clientWidth;
        const visible = (el: Element) => { const b = (el as HTMLElement).getBoundingClientRect(); return b.width > 0 && b.height > 0; };
        const name = (el: Element) => (el.getAttribute("aria-label") || (el as HTMLElement).innerText || el.getAttribute("title") || "").trim();
        const unlabeled = Array.from(document.querySelectorAll("input,select")).filter((e) => visible(e) && !(e as HTMLInputElement).labels?.length && !e.getAttribute("aria-label")).length;
        const clipped = (el: Element) => { for (let p = el.parentElement; p && p.tagName !== "MAIN"; p = p.parentElement) { const ox = getComputedStyle(p).overflowX; if (["auto", "scroll", "hidden", "clip"].includes(ox) && p.getBoundingClientRect().right <= vw + 1) return true; } return false; };
        return {
          overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
          mainOverflow: Math.max(0, ...Array.from(document.querySelectorAll("main, main *")).filter((e) => !clipped(e)).map((e) => Math.round((e as HTMLElement).getBoundingClientRect().right - vw))),
          h1: document.querySelectorAll("h1").length,
          unnamed: Array.from(document.querySelectorAll("a[href],button")).filter((e) => visible(e) && !name(e)).length,
          unlabeled,
          svgNamed: Array.from(document.querySelectorAll("svg[role=img]")).every((s) => !!s.getAttribute("aria-label")),
        };
      });
      expect(r.overflow).toBeLessThanOrEqual(1);
      expect(r.mainOverflow).toBeLessThanOrEqual(1);
      expect(r.h1).toBeGreaterThanOrEqual(1);
      expect(r.unnamed).toBe(0);
      expect(r.unlabeled).toBe(0);
      expect(r.svgNamed).toBe(true);
    });
  }
}
